using System; using AssemblyZero.Domain.EP04; class RouteProbe { static void Main(){var w=new WorldSimulation(HardwareCatalog.Create());foreach(var c in new[]{new WorldCommand{Kind=CommandKind.Build,Building=BuildingKind.Processor,X=12,Z=24,Factory=1},new WorldCommand{Kind=CommandKind.Build,Building=BuildingKind.Manufacturer,X=20,Z=24,Factory=1}}){w.Enqueue(c);w.FlushCommands();if(!w.LastResult.Success)throw new Exception(w.LastResult.Message);}Console.WriteLine(w.State.Routes.Count);}}